import json


def agrupar_por(ruta_json, clave):
    with open(ruta_json, encoding="utf-8") as f:
        datos = json.load(f)
    grupos = {}
    for item in datos:
        grupos.setdefault(item[clave], []).append(item["nombre"])
    return grupos


def a_json(d):
    return json.dumps(d, sort_keys=True, ensure_ascii=False)


def de_json(texto):
    return json.loads(texto)

